function maximizeGreatness(nums) {
  // Maximum bipartite matching: position i may take value j when nums[j] > nums[i].
  const n = nums.length;
  const owner = new Array(n).fill(-1);
  const tryAssign = (i, visited) => {
    for (let j = 0; j < n; j++) {
      if (nums[j] > nums[i] && !visited[j]) {
        visited[j] = true;
        if (owner[j] === -1 || tryAssign(owner[j], visited)) {
          owner[j] = i;
          return true;
        }
      }
    }
    return false;
  };
  let total = 0;
  for (let i = 0; i < n; i++) {
    if (tryAssign(i, new Array(n).fill(false))) total++;
  }
  return total;
}

